using System.Windows; using ANLAbel.App.ViewModels;
namespace ANLAbel.App;
public partial class AnalyticsWindow : Window { private readonly AnalyticsViewModel _viewModel; private readonly Action _openHistory; public AnalyticsWindow(MainViewModel main, Action openHistory) { InitializeComponent(); _openHistory = openHistory; _viewModel = new AnalyticsViewModel(main.ReadPrintHistorySnapshotAsync); DataContext = _viewModel; } private async void Window_Loaded(object s, RoutedEventArgs e) { Loaded -= Window_Loaded; await _viewModel.RefreshAsync(); } private async void Refresh_Click(object s, RoutedEventArgs e) => await _viewModel.RefreshAsync(); private void History_Click(object s, RoutedEventArgs e) { _openHistory(); Activate(); } private void Close_Click(object s, RoutedEventArgs e) => Close(); }
